      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "ACT-1004-1239, a larger amide/heteroaromatic drug, has an absolute oral bioavailability of 53% in healthy subjects, supporting high F for a similarly sized query.",
