    {
      "card_ids": ["C12"],
      "claim": "Lenvatinib, an orally bioavailable kinase inhibitor with amide and heteroaromatic ether, has an absolute bioavailability of about 85%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Venadaparib, an indazole-containing PARP inhibitor, shows good oral bioavailability, directly relevant to the query's indazole core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Bromazepam, a fused heteroaromatic drug, has an absolute oral bioavailability of 86%, supporting high F for the fused heteroaromatic query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Ilomastat, a peptidomimetic hydroxamate MMP inhibitor, had poor oral bioavailability; however, its peptide/hydroxamate liabilities are absent in the query, so this low-F evidence is weakly transferable.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is predicted to have high oral bioavailability (F >= 20%) because the most transferable experimental evidence, including multiple structurally related amide/heteroaromatic drugs with measured absolute F values of 53–86%, overwhelmingly supports high F; the only low-F analogue (ilomastat) is a peptidomimetic hydroxamate with liabilities absent in the query.",
